+import { readFileSync } from 'node:fs';
+import { fileURLToPath } from 'node:url';
+import { describe, expect, it } from 'vitest';
+import { loadShopSettings, type Env } from './config.ts';
+
+const dockerfile = readFileSync(fileURLToPath(new URL('../Dockerfile', import.meta.url)), 'utf8');
+
+/** The image's environment as Docker reads it, from its `ENV` lines. */
+function imageEnv(): Env {
+  const env: Env = {};
+  for (const line of dockerfile.split('\n')) {
+    const match = /^ENV\s+(\S+)(?:\s+(.*))?$/.exec(line.trim());
+    if (!match) continue;
+    const [, first, rest] = match;
+    if (first === undefined) continue;
+    // `ENV KEY=value` and `ENV KEY value` both set one variable.
+    const eq = first.indexOf('=');
+    if (eq !== -1) env[first.slice(0, eq)] = first.slice(eq + 1);
+    else env[first] = rest ?? '';
+  }
+  return env;
+}
+
+describe('demo app image', () => {
+  it('sets shop settings the app parses', () => {
+    // Docker only reads `#` as a comment at the start of a line, so an inline one becomes
+    // part of the value and loadShopSettings throws on it at runtime.
+    const env = imageEnv();
+    expect(env.FREE_SHIPPING_MIN_CENTS).toBeDefined();
+    expect(() => loadShopSettings(env)).not.toThrow();
+  });
+});
